//! Built-in starter content (T-533): a small, read-only library of our own
//! procedural figures and wireframe 3D objects, shown and playable on a
//! fresh data dir so CRÉATION › Figures and CRÉATION › Objets 3D are never
//! empty. Everything here is generated by code (maths over our own
//! parameters): nothing is copied from another product or a protected
//! library. These are never written to disk nor baked into a project; a
//! user figure or object of the same name shadows the built-in, and the
//! operator can play or duplicate them but not delete or overwrite them.

use crate::figures::{Figure, FigureFrame, LoopMode, RateUnit, Stroke};
use crate::wire::WireObject;
use std::f32::consts::{PI, TAU};

/// Green, our default beam colour.
const GREEN: [u8; 3] = [0, 255, 0];
const CYAN: [u8; 3] = [0, 255, 255];
const MAGENTA: [u8; 3] = [255, 0, 255];
const RED: [u8; 3] = [255, 60, 60];
const YELLOW: [u8; 3] = [255, 220, 0];
const BLUE: [u8; 3] = [60, 120, 255];
const WHITE: [u8; 3] = [255, 255, 255];

// ---------------------------------------------------------------------------
// Figures (2D)
// ---------------------------------------------------------------------------

/// One lit stroke of a figure.
fn stroke(points: Vec<[f32; 2]>, color: [u8; 3]) -> Stroke {
    Stroke { points, color, lit: true, part: 0 }
}

/// A closed outline: the first point repeated at the end (patterns rule).
fn closed(mut points: Vec<[f32; 2]>) -> Vec<[f32; 2]> {
    if let Some(&first) = points.first() {
        if points.last() != Some(&first) {
            points.push(first);
        }
    }
    points
}

/// A single-frame figure made of one closed outline.
fn outline(name: &str, color: [u8; 3], points: Vec<[f32; 2]>) -> Figure {
    one_frame(name, vec![stroke(closed(points), color)])
}

/// A single-frame figure made of the given strokes.
fn one_frame(name: &str, strokes: Vec<Stroke>) -> Figure {
    Figure { name: name.to_string(), frames: vec![FigureFrame { strokes }], ..Figure::default() }
}

/// `n` points of a parametric curve, `t` running 0..1 (end included).
fn curve(n: usize, f: impl Fn(f32) -> [f32; 2]) -> Vec<[f32; 2]> {
    (0..=n).map(|i| f(i as f32 / n as f32)).collect()
}

/// A regular polygon of `sides` vertices, radius `r`, first vertex up.
fn polygon(sides: usize, r: f32) -> Vec<[f32; 2]> {
    (0..sides).map(|i| {
        let a = PI / 2.0 + i as f32 / sides as f32 * TAU;
        [r * a.cos(), r * a.sin()]
    }).collect()
}

/// A point `len` from `from` along a limb at elevation `e` (radians, 0 =
/// straight down, π/2 = horizontal, π = straight up); `right` mirrors the
/// side. Used to place the stick dancer's and the silhouette's limbs.
fn dir_pt(from: [f32; 2], e: f32, len: f32, right: bool) -> [f32; 2] {
    let sx = if right { 1.0 } else { -1.0 };
    [from[0] + sx * len * e.sin(), from[1] - len * e.cos()]
}

/// `n + 1` points of a circular arc of centre `c`, radius `r`, from
/// `from_deg` to `to_deg` (degrees), both ends included.
fn arc(c: [f32; 2], r: f32, from_deg: f32, to_deg: f32, n: usize) -> Vec<[f32; 2]> {
    (0..=n)
        .map(|i| {
            let a = (from_deg + (to_deg - from_deg) * i as f32 / n as f32).to_radians();
            [c[0] + r * a.cos(), c[1] + r * a.sin()]
        })
        .collect()
}

/// The built-in figures, in no particular order (the UI sorts by name).
pub fn builtin_figures() -> Vec<Figure> {
    let mut figs = vec![
        heart(),
        flower(6),
        arrow(),
        lightning(),
        infinity(),
        outline("Losange", CYAN, vec![[0.0, 0.85], [0.6, 0.0], [0.0, -0.85], [-0.6, 0.0]]),
        outline("Pentagone", GREEN, polygon(5, 0.85)),
        outline("Hexagone", BLUE, polygon(6, 0.85)),
        crescent(),
        droplet(),
        spiral(),
        wave(),
        beating_heart(),
        dancer_stick(),
        dancer_silhouette(),
        dancer_3d(),
        star5(),
        star6(),
        circle_fig(),
        triangle(),
        square_fig(),
        octagon(),
        sun(),
        butterfly(),
        gear(),
        house(),
        fir_tree(),
        cloud(),
        music_note(),
        crown(),
        bowtie(),
        shooting_star(),
    ];
    for f in &mut figs {
        // Our own content is already in range; keep it safe anyway.
        let _ = f.validate();
    }
    figs
}

/// A heart curve (our own parametrisation), scaled into the field.
fn heart() -> Figure {
    let pts = curve(72, |t| {
        let a = t * TAU;
        let x = 16.0 * a.sin().powi(3);
        let y = 13.0 * a.cos() - 5.0 * (2.0 * a).cos() - 2.0 * (3.0 * a).cos() - (4.0 * a).cos();
        [x / 17.0, y / 17.0 + 0.1]
    });
    outline("Cœur", RED, pts)
}

/// A rose/flower of `petals` petals (r = cos(k·θ)).
fn flower(petals: usize) -> Figure {
    let k = petals as f32;
    let pts = curve(240, |t| {
        let a = t * TAU;
        let r = 0.9 * (k * a).cos().abs().max(0.02);
        [r * a.cos(), r * a.sin()]
    });
    outline(&format!("Fleur {petals} pétales"), MAGENTA, pts)
}

/// An upward arrow outline.
fn arrow() -> Figure {
    outline("Flèche", GREEN, vec![
        [-0.25, -0.8], [-0.25, 0.1], [-0.55, 0.1], [0.0, 0.8],
        [0.55, 0.1], [0.25, 0.1], [0.25, -0.8],
    ])
}

/// A zig-zag lightning bolt outline.
fn lightning() -> Figure {
    outline("Éclair", YELLOW, vec![
        [0.1, 0.85], [-0.45, 0.05], [-0.1, 0.05], [-0.35, -0.85],
        [0.45, 0.1], [0.08, 0.1], [0.35, 0.85],
    ])
}

/// A lemniscate (∞) through the origin.
fn infinity() -> Figure {
    let pts = curve(96, |t| {
        let a = t * TAU;
        let d = 1.0 + a.sin().powi(2);
        [0.85 * a.cos() / d, 0.5 * a.sin() * a.cos() / d]
    });
    outline("Infini", CYAN, pts)
}

/// A crescent moon: outer circle, back through an inner arc.
fn crescent() -> Figure {
    let outer = curve(48, |t| {
        let a = -PI / 2.5 + t * (TAU - 2.0 * PI / 2.5);
        [0.8 * a.cos(), 0.8 * a.sin()]
    });
    let inner = curve(32, |t| {
        let a = (TAU - PI / 2.5) - t * (TAU - 2.0 * PI / 2.5);
        [0.35 + 0.7 * a.cos(), 0.7 * a.sin()]
    });
    outline("Croissant", WHITE, outer.into_iter().chain(inner).collect())
}

/// A teardrop / water drop: a point at the top rounding into a disc.
fn droplet() -> Figure {
    let pts = curve(80, |t| {
        let a = t * TAU;
        // A circle pinched to a cusp at the top.
        let r = 0.7 * (1.0 - a.sin());
        [r * a.cos(), r * a.sin() - 0.1]
    });
    outline("Goutte", BLUE, pts)
}

/// An Archimedean spiral (an open stroke, not closed).
fn spiral() -> Figure {
    let pts = curve(200, |t| {
        let a = t * 5.0 * TAU;
        let r = 0.08 + 0.82 * t;
        [r * a.cos(), r * a.sin()]
    });
    one_frame("Spirale", vec![stroke(pts, GREEN)])
}

/// A sine wave across the field (an open stroke).
fn wave() -> Figure {
    let pts = curve(120, |t| {
        let x = -0.9 + 1.8 * t;
        [x, 0.5 * (t * 3.0 * TAU).sin()]
    });
    one_frame("Vague", vec![stroke(pts, CYAN)])
}

/// An animated heart that beats: four frames at different sizes, stepped
/// on the beat (the example animated figure, T-533).
fn beating_heart() -> Figure {
    let base = curve(72, |t| {
        let a = t * TAU;
        let x = 16.0 * a.sin().powi(3);
        let y = 13.0 * a.cos() - 5.0 * (2.0 * a).cos() - 2.0 * (3.0 * a).cos() - (4.0 * a).cos();
        [x / 17.0, y / 17.0 + 0.1]
    });
    let frames = [1.0_f32, 0.82, 1.0, 1.12]
        .into_iter()
        .map(|k| {
            let pts = closed(base.iter().map(|p| [p[0] * k, p[1] * k]).collect());
            FigureFrame { strokes: vec![stroke(pts, RED)] }
        })
        .collect();
    Figure { name: "Cœur qui bat".to_string(), frames, rate: 2.0, per: RateUnit::Beat, loop_mode: LoopMode::Loop, ..Figure::default() }
}

/// An animated stick-figure dancer (T-533): a head (small circle), a
/// spine, two arms and two legs, each a lit stroke. The joint elevations
/// are our own sinusoids of the frame phase, so arms and legs sweep
/// through a believable, looped dance cycle. Our own geometry, drawn by
/// maths: nothing traced from any product's content.
fn dancer_stick() -> Figure {
    const N: usize = 8;
    let frames = (0..N)
        .map(|i| {
            let w = i as f32 / N as f32 * TAU;
            let sway = 0.06 * w.sin();
            let hip = [sway * 0.5, -0.02];
            let shoulder = [sway, 0.30];
            let head_c = [sway, 0.48];
            // Arms raise in turn (one up while the other is lower), elbows
            // bending on the off-beat.
            let (aru, alu) = (1.1 + 1.0 * w.sin(), 1.1 - 1.0 * w.sin());
            let (arf, alf) = (aru + 0.4 * w.cos(), alu - 0.4 * w.cos());
            let elbow_r = dir_pt(shoulder, aru, 0.15, true);
            let hand_r = dir_pt(elbow_r, arf, 0.14, true);
            let elbow_l = dir_pt(shoulder, alu, 0.15, false);
            let hand_l = dir_pt(elbow_l, alf, 0.14, false);
            // Legs step side to side (one lifts while the other plants),
            // knees bending a little past the thigh.
            let (lrt, llt) = (0.18 + 0.32 * w.sin().max(0.0), 0.18 + 0.32 * (-w.sin()).max(0.0));
            let knee_r = dir_pt(hip, lrt, 0.17, true);
            let foot_r = dir_pt(knee_r, lrt + 0.18, 0.17, true);
            let knee_l = dir_pt(hip, llt, 0.17, false);
            let foot_l = dir_pt(knee_l, llt + 0.18, 0.17, false);
            let head = closed(arc(head_c, 0.1, 0.0, 360.0, 20));
            FigureFrame {
                strokes: vec![
                    stroke(head, CYAN),
                    stroke(vec![[head_c[0], head_c[1] - 0.1], shoulder, hip], CYAN),
                    stroke(vec![shoulder, elbow_r, hand_r], CYAN),
                    stroke(vec![shoulder, elbow_l, hand_l], CYAN),
                    stroke(vec![hip, knee_r, foot_r], CYAN),
                    stroke(vec![hip, knee_l, foot_l], CYAN),
                ],
            }
        })
        .collect();
    Figure { name: "Danseuse".to_string(), frames, rate: 4.0, per: RateUnit::Beat, loop_mode: LoopMode::Loop, ..Figure::default() }
}

/// A point `len` from `from` at elevation `e` from straight down
/// (0 = down, π = up); `right` mirrors x. The 2D sibling of `limb3`.
fn limb2(from: [f32; 2], e: f32, len: f32, right: bool) -> [f32; 2] {
    let sx = if right { 1.0 } else { -1.0 };
    [from[0] + sx * len * e.sin(), from[1] - len * e.cos()]
}

/// A smooth tapered capsule from `a` (half-width `wa`) to `b` (half-width
/// `wb`): one straight side, a rounded cap at `b`, the other side, a
/// rounded cap at `a`. A closed outline — a limb segment with soft ends.
fn stadium(a: [f32; 2], b: [f32; 2], wa: f32, wb: f32) -> Vec<[f32; 2]> {
    let (dx, dy) = (b[0] - a[0], b[1] - a[1]);
    let len = (dx * dx + dy * dy).sqrt().max(1e-6);
    let (nx, ny) = (-dy / len, dx / len); // left normal
    let ang = dy.atan2(dx).to_degrees(); // direction of a→b
    let mut p = vec![[a[0] + nx * wa, a[1] + ny * wa], [b[0] + nx * wb, b[1] + ny * wb]];
    p.extend(arc(b, wb, ang + 90.0, ang - 90.0, 6)); // cap over b
    p.push([a[0] - nx * wa, a[1] - ny * wa]);
    p.extend(arc(a, wa, ang - 90.0, ang - 270.0, 6)); // cap over a
    closed(p)
}

/// An animated dancer silhouette (T-534): a full, rounded body — a head, a
/// tapered leotard torso, and arms and legs built from smooth capsules
/// (`stadium`) with soft ends. Eight frames carry a flowing dance: a port
/// de bras (arms sweeping up and down, right leading), a hip sway and bob,
/// and the right leg extending to a pointed side extension while the left
/// stands in a soft plié. Our own geometry, all maths from the joints:
/// nothing traced from any product's content.
fn dancer_silhouette() -> Figure {
    const N: usize = 8;
    let frames = (0..N)
        .map(|i| {
            let p = i as f32 / N as f32 * TAU;
            let sway = 0.04 * p.sin();
            let bob = 0.015 * (2.0 * p).sin();
            // Spine landmarks.
            let hip_c = [sway, -0.05 + bob];
            let chest = [sway * 0.7, 0.30 + bob];
            let head_c = [sway * 0.5, 0.54 + bob];
            let sr = [chest[0] + 0.12, chest[1] + 0.04];
            let sl = [chest[0] - 0.12, chest[1] + 0.04];
            let hr = [hip_c[0] + 0.08, hip_c[1]];
            let hl = [hip_c[0] - 0.08, hip_c[1]];
            // Port de bras: arms sweep up and down, the right one leading.
            let aru = 2.1 + 0.8 * p.sin();
            let alu = 2.1 - 0.8 * p.sin();
            let elbow_r = limb2(sr, aru, 0.17, true);
            let wrist_r = limb2(elbow_r, aru + 0.25 * p.cos(), 0.16, true);
            let elbow_l = limb2(sl, alu, 0.17, false);
            let wrist_l = limb2(elbow_l, alu - 0.25 * p.cos(), 0.16, false);
            // Left leg stands in a soft plié; the right extends, pointed.
            let knee_l = limb2(hl, 0.12, 0.20, false);
            let ankle_l = limb2(knee_l, 0.06, 0.20, false);
            let legr = 0.25 + 0.5 * p.sin().max(0.0);
            let knee_r = limb2(hr, legr, 0.20, true);
            let ankle_r = limb2(knee_r, legr + 0.15, 0.20, true);
            // Waist points pinch the torso between chest and hips.
            let wr = [chest[0] + 0.07, (chest[1] + hip_c[1]) * 0.5];
            let wl = [chest[0] - 0.07, (chest[1] + hip_c[1]) * 0.5];
            let torso = closed(vec![sl, sr, wr, hr, hl, wl]);
            FigureFrame {
                strokes: vec![
                    stroke(closed(arc(head_c, 0.1, 0.0, 360.0, 22)), MAGENTA),
                    stroke(torso, MAGENTA),
                    stroke(stadium(sr, elbow_r, 0.045, 0.04), MAGENTA),
                    stroke(stadium(elbow_r, wrist_r, 0.04, 0.03), MAGENTA),
                    stroke(stadium(sl, elbow_l, 0.045, 0.04), MAGENTA),
                    stroke(stadium(elbow_l, wrist_l, 0.04, 0.03), MAGENTA),
                    stroke(stadium(hr, knee_r, 0.075, 0.06), MAGENTA),
                    stroke(stadium(knee_r, ankle_r, 0.06, 0.035), MAGENTA),
                    stroke(stadium(hl, knee_l, 0.075, 0.06), MAGENTA),
                    stroke(stadium(knee_l, ankle_l, 0.06, 0.035), MAGENTA),
                ],
            }
        })
        .collect();
    Figure { name: "Danseuse silhouette".to_string(), frames, rate: 4.0, per: RateUnit::Beat, loop_mode: LoopMode::Loop, ..Figure::default() }
}

/// A star of `points` points: outer radius `ro`, inner `ri`, first spike up.
fn star(points: usize, ro: f32, ri: f32) -> Vec<[f32; 2]> {
    (0..2 * points)
        .map(|i| {
            let r = if i % 2 == 0 { ro } else { ri };
            let a = PI / 2.0 + i as f32 / (2 * points) as f32 * TAU;
            [r * a.cos(), r * a.sin()]
        })
        .collect()
}

fn star5() -> Figure {
    outline("Étoile", YELLOW, star(5, 0.9, 0.38))
}

fn star6() -> Figure {
    outline("Étoile 6 branches", CYAN, star(6, 0.9, 0.5))
}

fn circle_fig() -> Figure {
    outline("Cercle", GREEN, curve(64, |t| {
        let a = t * TAU;
        [0.85 * a.cos(), 0.85 * a.sin()]
    }))
}

fn triangle() -> Figure {
    outline("Triangle", BLUE, polygon(3, 0.9))
}

fn square_fig() -> Figure {
    outline("Carré", GREEN, vec![[-0.7, 0.7], [0.7, 0.7], [0.7, -0.7], [-0.7, -0.7]])
}

fn octagon() -> Figure {
    outline("Octogone", MAGENTA, polygon(8, 0.85))
}

/// A sun: a core circle ringed by twelve rays.
fn sun() -> Figure {
    let core = closed(curve(40, |t| {
        let a = t * TAU;
        [0.42 * a.cos(), 0.42 * a.sin()]
    }));
    let mut strokes = vec![stroke(core, YELLOW)];
    for i in 0..12 {
        let a = i as f32 / 12.0 * TAU;
        strokes.push(stroke(vec![[0.55 * a.cos(), 0.55 * a.sin()], [0.9 * a.cos(), 0.9 * a.sin()]], YELLOW));
    }
    one_frame("Soleil", strokes)
}

/// A butterfly curve (Temple Fay), scaled into the field.
fn butterfly() -> Figure {
    let pts = curve(720, |t| {
        let th = t * 12.0 * PI;
        let bracket = th.cos().exp() - 2.0 * (4.0 * th).cos() - (th / 12.0).sin().powi(5);
        [th.sin() * bracket / 5.2, th.cos() * bracket / 5.2]
    });
    outline("Papillon", MAGENTA, pts)
}

/// A cog/gear wheel: square teeth around the rim.
fn gear() -> Figure {
    const TEETH: usize = 12;
    let pts = curve(TEETH * 24, |t| {
        let a = t * TAU;
        let tooth = (a * TEETH as f32).sin().signum();
        let r = 0.72 + 0.12 * tooth;
        [r * a.cos(), r * a.sin()]
    });
    outline("Engrenage", WHITE, pts)
}

/// A little house: walls and a peaked roof.
